import {renderAgentActivity} from './agent-activity';
import {mountSiteTabs} from './site-tabs';
import {libraryMarkup,importMarkup,bindLibrary} from './artifact-library';
import {runBrowserOperation} from './nstack-browser';
import QRCode from 'qrcode';
import {INVITE_KEY,inviteCode,inviteUrl} from './invite';
import {imageComposer,imageReferences,mountInterviewImages,draftImages,clearDraftImages,imageUploadBusy} from './interview-images';
import {renderMarkdown} from './markdown';
import {nstackSettings,nstackPermissions,attachNStackBridge,openNStackApp} from './nstack';
import {generateSecretKey,finalizeEvent,nip19,nip44,getPublicKey} from 'nostr-tools';
import {readNostrProfile,verifiedProfile,isChatSubmitKey} from './identity';

type RecordData = Record<string, any>;
declare global {interface Window {nostr?: {getPublicKey():Promise<string>;signEvent(event:RecordData):Promise<any>;nip44?:{decrypt(pubkey:string,ciphertext:string):Promise<string>}}}}
const app=document.querySelector<HTMLDivElement>('#app')!;
const KEY='byo-freedom.identity.v1', MODE='byo-freedom.signer.v1';
const incomingInvite=inviteCode(new URL(location.href));
if(incomingInvite){sessionStorage.setItem(INVITE_KEY,incomingInvite);history.replaceState(null,'','/'+location.hash);}
let inviteAttempt:Promise<string>|null=null;
async function joinPendingInvite(){const code=sessionStorage.getItem(INVITE_KEY);if(!code)return null;if(!inviteAttempt)inviteAttempt=api('/api/join','POST',{code}).then(result=>{sessionStorage.removeItem(INVITE_KEY);sessionStorage.removeItem('byo-freedom.return-app');return '#/projects/'+result.id;}).finally(()=>{inviteAttempt=null});return inviteAttempt;}

let me:RecordData|null=null, projects:RecordData[]=[], current:RecordData|null=null;
let tab=localStorage.getItem('byo-freedom.tab')||'chat', selectedSnapshot:string|null=null, selectedVersion:string|null=null, editing=false, generation=0, pollTimer:ReturnType<typeof setTimeout>|undefined;
let activeRoute='', lastRenderKey='', busy=false,chatComposing=false,lastChatCompositionEnd=0;
const e=(s:any)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const safeUrl=(s:any)=>{if(!s||!String(s).trim())return '';try{const u=new URL(String(s),location.origin);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const date=(s:any)=>{const d=new Date(s);return Number.isNaN(d.valueOf())?'':d.toLocaleDateString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})};
const bytesHex=(b:Uint8Array)=>Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');
const hexBytes=(h:string)=>new Uint8Array(h.match(/.{2}/g)!.map(s=>parseInt(s,16)));
const sha=async(data:BufferSource)=>bytesHex(new Uint8Array(await crypto.subtle.digest('SHA-256',data)));
const storageGet=(k:string)=>{try{return localStorage.getItem(k)}catch{return null}};
function toast(message:string){const t=document.querySelector<HTMLDivElement>('#toast')!;t.textContent=message;t.style.display='block';setTimeout(()=>t.style.display='none',4500)}
function fail(error:any){toast(error instanceof Error?error.message:String(error))}
async function sign(event:RecordData){if(event.kind===0)throw new Error('BYO Freedom never publishes Nostr profiles.');if(storageGet(MODE)==='extension'){if(!window.nostr)throw new Error('Your Nostr signer is unavailable. Open this page in your signer’s browser or reconnect it.');return window.nostr.signEvent(event)}const key=storageGet(KEY);if(!key)throw new Error('Please sign in again.');return finalizeEvent(event as any,hexBytes(key))}
function nstackSigner(){
 if(storageGet(MODE)==='extension'){
  if(!window.nostr)throw new Error('Your Nostr signer is unavailable. Reconnect it and retry.');
  return window.nostr;
 }
 const key=storageGet(KEY);if(!key)throw new Error('Please sign in again.');
 return {getPublicKey:async()=>getPublicKey(hexBytes(key)),signEvent:sign,nip44:{decrypt:async(pubkey:string,ciphertext:string)=>nip44.v2.decrypt(ciphertext,nip44.v2.utils.getConversationKey(hexBytes(key),pubkey))}};
}
async function api(path:string,method='GET',data?:RecordData,options?:{signal?:AbortSignal}){options?.signal?.throwIfAborted();const url=new URL(path,location.origin).href;const body=data===undefined?undefined:JSON.stringify(data);const tags=[['u',url],['method',method],['nonce',crypto.randomUUID()]];if(body!==undefined)tags.push(['payload',await sha(new TextEncoder().encode(body))]);options?.signal?.throwIfAborted();const event=await sign({kind:27235,created_at:Math.floor(Date.now()/1000),tags,content:''});options?.signal?.throwIfAborted();const auth=btoa(JSON.stringify(event));const res=await fetch(url,{method,body,signal:options?.signal,headers:{Authorization:`Nostr ${auth}`,...(body!==undefined?{'Content-Type':'application/json'}:{})},credentials:'omit'});const result=await res.json().catch(()=>({error:`Request failed (${res.status})`}));if(!res.ok){const err=new Error(result.error||`Request failed (${res.status})`);Object.assign(err,{status:res.status});throw err}return result}
function avatar(profile:RecordData={},large=false){const url=safeUrl(profile.avatar);return url?`<img class="avatar ${large?'profile-avatar':''}" src="${e(url)}" alt="${e(profile.name||'Your avatar')}" referrerpolicy="no-referrer">`:`<span class="avatar ${large?'profile-avatar':''}" aria-hidden="true">${e((profile.name||'You').slice(0,1).toUpperCase())}</span>`}
function header(){return `<header class="topbar"><a class="brand" href="#/projects"><span class="mark" aria-hidden="true"></span>BYO Freedom</a><div class="top-actions">${me?`${me.admin?'<span class="admin-badge">Admin workshop</span>':''}<button class="account" data-action="profile" aria-label="Open your profile">${avatar(me.profile)}<span class="account-name">${e(me.profile?.name||'Your profile')}</span></button>`:'<span class="eyebrow" style="margin:0">Ideas into independence</span>'}</div></header>`}
function breadcrumb(items:Array<[string,string?]>){return `<nav class="crumb" aria-label="Breadcrumb">${items.map(([label,route],i)=>`${i?'<span aria-hidden="true">/</span>':''}${route?`<a href="#${e(route)}">${e(label)}</a>`:`<span>${e(label)}</span>`}`).join('')}</nav>`}
function renderEntry(){app.innerHTML=header()+`<main class="entry"><section><div class="eyebrow">Bring your own freedom</div><h1>A little idea.<br>A little <em>more free.</em></h1><p class="entry-copy">What would give you more freedom? Explore it with an agent, shape a design, and help bring something useful into the world.</p><div class="entry-meta"><span>Freedom & Bitcoin</span><span>Your words. Your ideas.</span></div></section><section class="entry-card"><div class="eyebrow">Your workshop starts here</div><h2>${sessionStorage.getItem(INVITE_KEY)?'Join your project.':'Make room for your ideas.'}</h2>${sessionStorage.getItem(INVITE_KEY)?'<p class="help">Your project invitation is saved. Sign in or create an account to join and open it automatically.</p>':''}<p class="muted">No account forms. Start with a private browser identity, or use your Nostr signer.</p><button class="primary" data-action="anon">Create anonymous account <span aria-hidden="true">↗</span></button><button data-action="extension">Log in with Nostr extension</button><p class="help">Your anonymous key stays in this browser. Clearing its storage or changing devices loses access unless you export your recovery key.</p><div class="divider"></div><button class="text-button small" data-action="import">Restore a recovery key</button><p class="help">On a phone, use a NIP-07 compatible signer browser to sign in with an existing Nostr identity.</p></section></main>`}
async function loadMe(){const account=await api('/api/me');account.appProfile={...account.profile};if(storageGet(MODE)==='extension'){let profile=null;try{const lookup=await api('/api/profile/nostr');profile=verifiedProfile(lookup.profile?.event,account.pubkey);}catch{}if(!profile)profile=await readNostrProfile(account.pubkey);if(profile){account.profile={name:profile.name||account.profile?.name||'Nostr identity',avatar:profile.avatar};account.nostrProfile={eventId:profile.event.id,createdAt:profile.event.created_at};}}me=account;return me}
function loginDestination(){const path=sessionStorage.getItem('byo-freedom.return-app');sessionStorage.removeItem('byo-freedom.return-app');return path&&/^\/apps\/[^/?#]+$/.test(path)?'#'+path:null;}
async function login(mode:string){if(mode==='anon'){let key=storageGet(KEY);if(!key){key=bytesHex(generateSecretKey());localStorage.setItem(KEY,key)}localStorage.setItem(MODE,'anonymous')}else{if(!window.nostr)throw new Error('No NIP-07 signer found. Use a compatible Nostr extension or signer browser, or create an anonymous account.');await window.nostr.getPublicKey();localStorage.setItem(MODE,'extension')}await loadMe();location.hash=loginDestination()||(mode!=='anon'||me!.profile?.name?'#/projects':'#/profile');await route()}
function modal(title:string,html:string,onSubmit?:(form:HTMLFormElement)=>Promise<void>){document.querySelector('.modal-backdrop')?.remove();const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${e(title)}</h2><button type="button" class="small ghost" data-close aria-label="Close dialog">✕</button></div><form>${html}</form></section>`;document.body.append(backdrop);const opener=document.activeElement as HTMLElement|null;const close=()=>{backdrop.remove();if(opener?.isConnected)opener.focus()};backdrop.querySelector('[data-close]')!.addEventListener('click',close);backdrop.addEventListener('click',ev=>{if(ev.target===backdrop)close()});backdrop.addEventListener('keydown',ev=>{if(ev.key==='Escape')close()});const form=backdrop.querySelector('form')!;form.addEventListener('submit',async ev=>{ev.preventDefault();const submit=form.querySelector<HTMLButtonElement>('[type=submit]');if(submit)submit.disabled=true;try{await onSubmit?.(form);close()}catch(err){let box=form.querySelector('.error-box');if(!box){box=document.createElement('div');box.className='error-box';box.setAttribute('role','alert');form.prepend(box)}box.textContent=(err as Error).message}finally{if(submit)submit.disabled=false}});backdrop.querySelector<HTMLElement>('input,textarea,select,button')?.focus();return backdrop}
function restore(){modal('Restore your browser identity',`<p class="muted">Enter the recovery key you exported from BYO Freedom. It is stored only in this browser and is never sent to the server.</p><label>Recovery key<input name="key" type="password" autocomplete="off" spellcheck="false" required placeholder="nsec1…"></label><div class="modal-actions"><button class="primary" type="submit">Restore account</button></div>`,async form=>{const value=String(new FormData(form).get('key')).trim();const decoded=nip19.decode(value);if(decoded.type!=='nsec')throw new Error('Please enter an nsec recovery key.');localStorage.setItem(KEY,bytesHex(decoded.data));localStorage.setItem(MODE,'anonymous');await loadMe();location.hash=loginDestination()||'#/projects';await route()})}
function exportKey(){const key=storageGet(KEY);if(storageGet(MODE)==='extension'||!key){toast('Your Nostr signer manages this account’s recovery key.');return}const nsec=nip19.nsecEncode(hexBytes(key));modal('Save your recovery key',`<p>Anyone with this key can act as you. Keep it somewhere private so you can recover your designs on another device.</p><label>Private recovery key<textarea readonly rows="3" autocomplete="off" spellcheck="false">${e(nsec)}</textarea></label><div class="modal-actions"><button type="button" data-download>Download recovery file</button><button type="submit" class="primary">I have saved it</button></div>`).querySelector('[data-download]')!.addEventListener('click',()=>{const blob=new Blob([`BYO Freedom private recovery key\n\n${nsec}\n\nKeep this private. Anyone with this key can access your account.\n`],{type:'text/plain'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='byo-freedom-recovery.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function profile(){if(!me)await loadMe();if(storageGet(MODE)==='extension'){renderNostrIdentity();return;}app.innerHTML=header()+`<main class="shell">${breadcrumb([['My Projects','/projects'],['Your profile']])}<div class="eyebrow">A name to your ideas</div><h1>Your corner of the workshop.</h1><p class="intro">Choose what people call you. A first name or a nickname is plenty.</p><form id="profile-form" class="form-grid"><div class="profile-upload">${avatar(me!.profile,true)}<div><label>Upload an avatar<input type="file" id="avatar-file" accept="image/jpeg,image/png,image/webp,image/gif"></label><p class="help">Uploaded directly to blossom.primal.net with your Nostr signature. Your picture will be public.</p><p class="help" id="upload-status" role="status"></p></div></div><label>Name<input name="name" value="${e(me!.profile?.name)}" maxlength="100" required autocomplete="nickname"></label><label>Avatar URL<input name="avatar" type="url" value="${e(me!.profile?.avatar)}" placeholder="https://…"></label><div class="row"><button class="primary" type="submit">Save profile</button><button type="button" data-action="projects">Back to projects</button></div></form><div class="divider"></div><div class="form-grid"><h2>Your identity</h2><p class="code muted">${e(me!.pubkey?nip19.npubEncode(me!.pubkey):'')}</p><p class="help">${storageGet(MODE)==='extension'?'You are signing with your Nostr extension. Your signer keeps your private key.':'Your anonymous identity is stored in this browser. Browser storage is not a backup. Save your recovery key before clearing storage or switching devices.'}</p><div class="row"><button data-action="export">Export recovery key</button><button class="ghost" data-action="logout">Sign out</button></div></div></main>`;document.querySelector('#profile-form')!.addEventListener('submit',async ev=>{ev.preventDefault();await act(async()=>{const f=new FormData(ev.target as HTMLFormElement);await api('/api/profile','PATCH',{name:f.get('name'),avatar:f.get('avatar')});await loadMe();toast('Profile saved');location.hash='#/projects'})});document.querySelector('#avatar-file')!.addEventListener('change',uploadAvatar)}
function renderNostrIdentity(){app.innerHTML=header()+`<main class="shell">${breadcrumb([['My Projects','/projects'],['Your Nostr identity']])}<div class="eyebrow">Your existing identity</div><h1>Your Nostr profile.</h1><div class="card form-grid"><div class="profile-upload">${avatar(me!.profile,true)}<div><h2>${e(me!.profile?.name||'Nostr identity')}</h2><p class="help">${me!.nostrProfile?'Read from your verified, signed Nostr profile.':'Showing your existing app profile. A verified Nostr profile is not available right now.'}</p></div></div><p class="code muted">${e(nip19.npubEncode(me!.pubkey))}</p><p class="muted">Your Nostr signer manages this identity. BYO Freedom reads your profile and never publishes or changes it.</p><div class="row"><button class="primary" data-action="projects">Back to projects</button><button class="ghost" data-action="logout">Sign out</button></div></div></main>`;}
async function uploadAvatar(ev:Event){const file=(ev.target as HTMLInputElement).files?.[0];if(!file)return;const status=document.querySelector('#upload-status')!;try{if(file.size>5*1024*1024)throw new Error('Choose a picture smaller than 5 MB.');if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw new Error('Choose a JPG, PNG, WebP or GIF picture.');status.textContent='Signing and uploading your picture…';const hash=await sha(await file.arrayBuffer());const now=Math.floor(Date.now()/1000);const event=await sign({kind:24242,created_at:now,content:'Upload BYO Freedom profile picture',tags:[['t','upload'],['x',hash],['expiration',String(now+300)]]});const res=await fetch('https://blossom.primal.net/upload',{method:'PUT',body:file,headers:{Authorization:`Nostr ${btoa(JSON.stringify(event))}`,'Content-Type':file.type},credentials:'omit'});if(!res.ok)throw new Error(`Blossom rejected the upload (${res.status}).`);const info=await res.json();const url=safeUrl(info.url);if(!url||new URL(url).protocol!=='https:')throw new Error('Blossom did not return a valid HTTPS image URL.');(document.querySelector('[name=avatar]') as HTMLInputElement).value=url;status.textContent='Uploaded. Save your profile to use this picture.'}catch(err){status.textContent=`Upload unavailable: ${(err as Error).message} Your browser or the Blossom server may restrict this request. You can enter an existing public image URL instead.`}}
async function renderProjects(){const data=await api('/api/projects');projects=data.projects||[];app.innerHTML=header()+`<main class="shell"><div class="heading-row"><div><div class="eyebrow">A place to make things happen</div><h1>My Projects</h1><p class="intro">Find your people. Bring an idea. See where it goes.</p></div>${me!.admin?'<button class="primary" data-action="new-project">+ Create project</button>':''}</div><form class="join-row" id="join-form"><label>Have a project code?<input name="code" placeholder="Enter your join code" required autocapitalize="characters" autocomplete="off"></label><button type="submit">Join project <span aria-hidden="true">↗</span></button></form>${projects.length?`<div class="section-row"><h2>Your workshops <span class="muted">(${projects.length})</span></h2></div><div class="cards">${projects.map(p=>`<button class="card project-card" data-project="${e(p.id)}"><div><div class="eyebrow">Project workshop</div><h3>${e(p.title)}</h3><p class="muted" style="font-size:.85rem">${e(p.description||'A shared space for independent ideas.')}</p></div><div class="card-footer"><span>Open project</span><span class="arrow" aria-hidden="true">↗</span></div></button>`).join('')}</div>`:`<div class="empty" style="margin-top:35px"><h3>Your next idea needs a home.</h3><p>Join a project with a code from your event organiser. Featured events appear here automatically while admission is open.</p></div>`}${me!.admin?`<section class="project-admin"><div class="section-row"><h2>Featured event</h2><button data-action="nstack-settings" class="small">NStack data connection</button><button class="small" data-action="featured">Manage auto admission</button></div><p class="help">A featured event automatically admits new visitors until the time you choose. ${data.settings?.featuredProjectId?`Current event: ${e(projects.find(p=>p.id===data.settings.featuredProjectId)?.title||data.settings.featuredProjectId)}. Until ${e(date(data.settings.featuredUntil))}.`:'No featured event is selected.'}</p></section>`:''}<p class="footer-note">Built around your ideas, with freedom and Bitcoin at the heart of the conversation.</p></main>`;document.querySelector('#join-form')!.addEventListener('submit',ev=>{ev.preventDefault();act(async()=>{const r=await api('/api/join','POST',{code:new FormData(ev.target as HTMLFormElement).get('code')});toast('You joined the project');location.hash=`#/projects/${r.project?.id||r.projectId||r.id}`})});document.querySelectorAll('[data-project]').forEach(el=>el.addEventListener('click',()=>location.hash=`#/projects/${el.getAttribute('data-project')}`))}
function createProject(){modal('Create a project',`<div class="form-grid"><label>Project name<input name="title" required maxlength="160" placeholder="Parkes Bush Bash 2026"></label><label>A little about it<textarea name="description" rows="3" maxlength="3000" placeholder="What brings this group together?"></textarea></label></div><div class="modal-actions"><button class="primary" type="submit">Create project</button></div>`,async form=>{const f=new FormData(form);const r=await api('/api/projects','POST',{title:f.get('title'),description:f.get('description')});location.hash=`#/projects/${r.project?.id||r.id}`})}
function featured(){modal('Feature an event',`<p class="muted">Visitors automatically join this project while its admission window is open.</p><div class="form-grid"><label>Project<select name="project"><option value="">No featured event</option>${projects.map(p=>`<option value="${e(p.id)}" ${p.id===me!.settings?.featuredProjectId?'selected':''}>${e(p.title)}</option>`).join('')}</select></label><label>Admission closes (your local time)<input name="until" type="datetime-local" value="${new Date(Date.now()+3*86400000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></label></div><div class="modal-actions"><button class="primary" type="submit">Save admission window</button></div>`,async form=>{const f=new FormData(form);const id=f.get('project');const until=String(f.get('until'));if(id&&!until)throw new Error('Choose when automatic admission closes.');await api('/api/settings','PATCH',{featuredProjectId:id||null,featuredUntil:id?new Date(until).toISOString():null});await loadMe();await renderProjects();toast('Featured event updated')})}
function projectNav(id:string,builder=false){return me!.admin?`<nav class="project-views" aria-label="Project workspace"><a ${builder?'':'aria-current="page"'} href="#/projects/${e(id)}">Design conversations</a><a ${builder?'aria-current="page"':''} href="#/projects/${e(id)}/site">Project Builder</a></nav>`:''}
function projectAdmin(p:RecordData){return `<section class="project-admin"><div class="section-row"><h2>Project settings</h2><div class="row"><button class="small" data-action="share-project">Share project · QR code</button><button class="small" data-action="project-settings">Edit project & join code</button></div></div><p class="help">Join code: <strong class="code">${e(p.joinCode||'Not available')}</strong></p></section>`}
async function renderProject(id:string){
 const [data,library,destinations]=await Promise.all([api(`/api/projects/${encodeURIComponent(id)}`),api(`/api/projects/${encodeURIComponent(id)}/library`),me!.admin?api('/api/projects'):Promise.resolve({projects:[]})]);current=data;const p=data.project;
 const others=(data.availableDesigns||[]).filter((d:RecordData)=>d.owner!==me!.pubkey);
 app.innerHTML=header()+`<main class="shell project-workspace">${breadcrumb([['My Projects','/projects'],[p.title]])}<div class="project-heading"><div class="project-title-row"><h1>${e(p.title)}</h1><a class="primary site-link" href="${e(me!.publicOrigin)}/sites/${encodeURIComponent(p.id)}" target="_blank" rel="noopener">View project site <span aria-hidden="true">↗</span></a></div><p class="intro">${e(p.description||'Bring a question, a tool you wish existed, or a trick worth sharing.')}</p></div>${projectNav(id)}
 <section aria-label="My designs"><div class="section-row"><h2>My Designs</h2><button class="primary" data-action="new-design">+ New design</button></div>${data.designs?.length?`<div class="project-card-grid">${data.designs.map((d:RecordData)=>designCard(d,data)).join('')}</div>`:`<div class="empty"><h3>What would you like to make?</h3><p>Start a design conversation and develop your idea. Build this now opens a linked build conversation; the chat shows whether building is available.</p><button data-action="new-design">Start your first interview <span aria-hidden="true">↗</span></button></div>`}</section>
 ${me!.admin?`<section aria-label="Other designs"><div class="section-row"><h2>Other people’s designs</h2><span class="badge">Admin access</span></div>${others.length?`<div class="project-card-grid">${others.map((d:RecordData)=>designCard(d,data)).join('')}</div>`:'<p class="help">Other participants’ designs appear here as they begin. Your own designs stay above.</p>'}</section>`:''}
 ${libraryMarkup(library.entries,me!.admin)}
 ${data.apps?.length?`<section aria-label="Project apps"><div class="section-row"><h2>Project apps</h2></div><p class="help">Use installed apps with saved data. Design conversations remain private.</p><div class="project-card-grid">${data.apps.map((a:RecordData)=>`<a class="card project-work-card" href="#/apps/${e(a.versionId)}" data-project-app="${e(a.versionId)}"><h3>${e(a.title)}</h3><p class="help">Version ${e(a.number)} · Saved app data</p><span class="card-action">Open app ↗</span></a>`).join('')}</div></section>`:''}</main>`;
 bindLibrary(id,library.entries,data.artifacts||[],destinations.projects,api,modal,()=>renderProject(id));
}
function designCard(d:RecordData,data:RecordData){const versions=allVersions({artifacts:(data.artifacts||[]).filter((a:RecordData)=>a.designId===d.id)});const latest=versions.at(-1);const builds=(data.implementations||[]).filter((i:RecordData)=>i.designId===d.id);return `<article class="card project-work-card"><span class="eyebrow">${d.owner===me!.pubkey?'Your design':'Participant design'}</span><h3><a href="#/designs/${e(d.id)}">${e(d.title||'New design')}</a></h3><p class="help">${d.currentSnapshotId?'Saved design':'Getting started'}${latest?' · Artefact v'+e(latest.number):''}${d.updatedAt?' · '+e(date(d.updatedAt)):''}</p>${d.owner!==me!.pubkey?`<p class="help design-owner">${e(d.ownerLabel||'Project participant')}</p>`:''}<div class="card-actions"><a class="small" data-design="${e(d.id)}" href="#/designs/${e(d.id)}">Continue design ↗</a>${builds.length?`<a class="small" href="#/implementations/${e(builds.at(-1).id)}">Continue build ↗</a>`:''}</div></article>`}
async function newDesign(){const p=current!.project;const r=await api(`/api/projects/${encodeURIComponent(p.id)}/designs`,'POST',{});location.hash=`#/designs/${r.design?.id||r.id}`}
async function shareProject(){const p=current!.project;if(!me?.admin||!p.joinCode)throw Error('Project sharing is available to admins.');const url=inviteUrl(me!.publicOrigin,p.joinCode);const box=modal('Share '+p.title,`<p>Share this link or QR code. After signing in or creating an account, visitors join this project and open it automatically.</p><p class="help">Anyone with this code can join as a participant. Change the join code in Project settings to stop future joins with this link.</p><label>Project invitation URL<input id="invite-url" readonly value="${e(url)}"></label><div class="modal-actions"><button type="button" id="invite-copy">Copy full URL</button></div><canvas id="invite-qr" role="img" aria-label="Project invitation QR code" style="display:block;max-width:100%;height:auto;margin:16px auto"></canvas><p class="help" id="invite-copy-status" role="status"></p>`);const input=box.querySelector<HTMLInputElement>('#invite-url')!;box.querySelector('#invite-copy')!.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url);box.querySelector('#invite-copy-status')!.textContent='Invitation URL copied';}catch{input.focus();input.select();box.querySelector('#invite-copy-status')!.textContent='Select and copy the invitation URL above.';}});await QRCode.toCanvas(box.querySelector<HTMLCanvasElement>('#invite-qr')!,url,{width:320,margin:4,errorCorrectionLevel:'M'});}
function projectSettings(){const p=current!.project;modal('Project settings',`<div class="form-grid"><label>Project name<input name="title" required maxlength="160" value="${e(p.title)}"></label><label>Description<textarea name="description" rows="3">${e(p.description)}</textarea></label><label>Join code<input name="joinCode" required value="${e(p.joinCode)}" autocomplete="off"></label></div><div class="modal-actions"><button type="button" class="danger" data-action="delete-project">Delete project</button><button class="primary" type="submit">Save changes</button></div>`,async form=>{await api(`/api/projects/${p.id}`,'PATCH',{title:new FormData(form).get('title'),description:new FormData(form).get('description'),joinCode:new FormData(form).get('joinCode')});if(location.hash.endsWith('/site'))await renderSiteBuilder(p.id);else await renderProject(p.id);toast('Project settings saved')})}
function deleteProject(){const p=current!.project;modal('Delete project',`<p>Delete <strong>${e(p.title)}</strong> and remove its entire public site, including all published contributions? Members will lose access to its interviews and apps. This is a project deletion, not a single design removal.</p><p class="help">Records and version history are retained privately for operator recovery. This cannot be undone here.</p><label>Type the project name to confirm<input name="confirmTitle" required autocomplete="off" aria-label="Project name to confirm deletion"></label><div class="modal-actions"><button type="button" data-action="project-settings">Cancel</button><button type="submit" class="danger">Delete project and site</button></div>`,async form=>{await api(`/api/projects/${p.id}`,'DELETE',{confirmTitle:new FormData(form).get('confirmTitle')});location.hash='#/projects';toast('Project and public site removed')})}
async function buildNow(){
 const design=current!.design;saveWorkspaceState();
 if(editing)throw Error('Save or cancel your design edits before building. Your draft is preserved.');
 if(selectedVersion||selectedSnapshot&&selectedSnapshot!==design.currentSnapshotId)throw Error('Return to the latest saved design before using Build this now.');
 if((document.querySelector<HTMLTextAreaElement>('#message-input')?.value||'').trim()||draftImages(design.id).length)throw Error('Send your design message first so the builder receives it. Your draft is preserved.');
 if(!design.currentSnapshotId)throw Error('Save a design revision or complete an interview reply before building.');
 const pendingKey=`byo-freedom.build-pending.${me!.pubkey}.${design.id}`;
 let pending:RecordData|null=null;try{pending=JSON.parse(storageGet(pendingKey)||'null')}catch{}
 const payload=pending&&pending.snapshotId===design.currentSnapshotId?pending:{requestId:crypto.randomUUID(),snapshotId:design.currentSnapshotId};
 localStorage.setItem(pendingKey,JSON.stringify(payload));
 const button=document.querySelector<HTMLButtonElement>('[data-action="implement-current"]');if(button){button.disabled=true;button.textContent='Starting build…';}
 try{const result=await api(`/api/designs/${design.id}/build`,'POST',payload);localStorage.removeItem(pendingKey);tab='chat';localStorage.setItem('byo-freedom.tab',tab);location.hash=`#/implementations/${result.implementation.id}`;}
 catch(error){if(button){button.disabled=false;button.textContent='Build this now';}throw error;}
}
async function buildOptions(){
 const designId=current!.design.id;saveWorkspaceState();if(editing)throw Error('Save or cancel your design edits before choosing a build source.');
 const data=await api(`/api/designs/${designId}/snapshots`);const snaps=(data.milestones||[]).map((m:RecordData)=>({...m,id:m.snapshotId}));const versions=allVersions(data);if(!snaps.length)throw Error('Save a design revision before choosing a build source.');
 modal('Build options',`<p>Open a separate administrator build conversation pinned to an exact saved design and optional starting artefact. This does not start a build until you send its first instruction.</p><div class="form-grid"><label>Design milestone<select name="snapshotId">${[...snaps].reverse().map((s:RecordData)=>`<option value="${e(s.id)}">Design ${e(s.number)} · ${e(s.title||'Design')} · ${e(s.state)}</option>`).join('')}</select></label><label>Starting artefact version<select name="startingVersionId"><option value="">Start a new artefact (or use imported reference)</option>${versions.map(v=>`<option value="${e(v.id)}">${e(v.artifactTitle)} · Version ${e(v.number)}</option>`).join('')}</select></label></div><div class="modal-actions"><button class="primary" type="submit">Open build chat</button></div>`,async form=>{const f=new FormData(form);const i=await api(`/api/designs/${designId}/implementations`,'POST',{snapshotId:f.get('snapshotId'),startingVersionId:f.get('startingVersionId')||null});tab='chat';location.hash=`#/implementations/${i.id}`;});
}
function allVersions(data:RecordData):RecordData[]{return (data.artifacts||[]).flatMap((a:RecordData)=>(a.versions||[]).map((v:RecordData)=>({...v,artifactId:a.id,artifactTitle:a.title}))).sort((a:RecordData,b:RecordData)=>new Date(a.createdAt||0).valueOf()-new Date(b.createdAt||0).valueOf())}
const draftKey=(kind:string,id:string)=>`byo-freedom.draft.${kind}.${id}`;
function saveWorkspaceState(){const composer=document.querySelector<HTMLTextAreaElement>('#message-input');if(composer&&current){localStorage.setItem(draftKey(current.implementation?'implementation':'design',current.implementation?.id||current.design.id),composer.value)}const edit=document.querySelector<HTMLTextAreaElement>('#document-editor');if(edit&&current)sessionStorage.setItem(`byo-freedom.edit.${current.design.id}`,edit.value)}
function buildResultCards(jobId:string,data:RecordData,versions:RecordData[]){const job=(data.jobs||[]).find((j:RecordData)=>j.id===jobId);const results=versions.filter(v=>v.jobId===jobId||v.id===job?.resultVersionId);return results.map(v=>`<article class="build-result" aria-label="Build result"><span class="eyebrow">Tested build result</span><h3>${e(v.artifactTitle)} · Artefact v${e(v.number)}</h3><p>From Design ${e(v.designPin?.designNumber||data.designPin?.designNumber||1)} · ${v.sitePublished?'Published on project site':'Private preview · not published to site'}</p><button class="small" data-version-select="${e(v.id)}">Preview version ${e(v.number)}</button></article>`).join('')}
function designModeNav(data:RecordData,impl:RecordData|undefined){const latest=(data.implementations||[]).at(-1);return `<nav class="design-modes" aria-label="Design and build"><a href="#/designs/${e(data.design.id)}" ${impl?'':'aria-current="page"'}>Design conversation</a>${latest?`<a href="#/implementations/${e(impl?.id||latest.id)}" ${impl?'aria-current="page"':''}>Build chat${data.implementations.length>1?' · '+data.implementations.length+' conversations':''}</a>`:'<span>Build when your design is ready</span>'}</nav>${impl&&(data.implementations||[]).length>1?`<label class="build-conversation-picker">Build conversation<select id="build-conversation">${[...data.implementations].reverse().map((i:RecordData)=>`<option value="${e(i.id)}" ${i.id===impl.id?'selected':''}>${e(date(i.createdAt))} · ${i.id===impl.id?'Current build':'Earlier build'}</option>`).join('')}</select></label>`:''}`}
async function workspace(kind:string,id:string,refresh=false){const token=generation;const data=await api(`/api/${kind==='design'?'designs':'implementations'}/${encodeURIComponent(id)}`);if(token!==generation)return;const routeKey=`${kind}/${id}`;const versions=allVersions(data);const snaps=data.snapshots||(data.snapshot?[data.snapshot]:[]);const job=(data.jobs||[]).filter((j:RecordData)=>!['complete','completed','succeeded','failed','error','cancelled','conflict','superseded'].includes(j.status)).at(-1);const failed=(data.jobs||[]).filter((j:RecordData)=>['failed','error','interrupted','conflict'].includes(j.status)).at(-1);const renderKey=JSON.stringify({data,selectedSnapshot,selectedVersion,editing},(key,value)=>key==='previewUrl'?undefined:value);if(refresh&&(editing||chatComposing||imageUploadBusy(id)||lastRenderKey===renderKey)){schedulePoll(kind,id,!!job);return}saveWorkspaceState();const messagesEl=document.querySelector('.messages');const previousScroll=messagesEl?.scrollTop||0;const atBottom=!messagesEl||messagesEl.scrollHeight-messagesEl.clientHeight-previousScroll<70;const editor=document.querySelector<HTMLTextAreaElement>('#document-editor');const editorScroll=editor?.scrollTop||0;const wasFocused=(document.activeElement as HTMLElement)?.id;const selection=wasFocused==='message-input'?(document.activeElement as HTMLTextAreaElement).selectionStart:null;current=data;activeRoute=routeKey;lastRenderKey=renderKey;const design=data.design;const impl=data.implementation;if(impl&&!selectedVersion&&!selectedSnapshot){const ownJobs=new Set((data.jobs||[]).map((j:RecordData)=>j.id));const built=versions.filter(v=>ownJobs.has(v.jobId)||(data.jobs||[]).some((j:RecordData)=>j.resultVersionId===v.id)).at(-1);if(built)selectedVersion=built.id;}const latest=snaps.find((s:RecordData)=>s.id===design.currentSnapshotId)||snaps.at(-1);const snap=snaps.find((s:RecordData)=>s.id===selectedSnapshot)||latest;const version=versions.find(v=>v.id===selectedVersion);const content=version?`<iframe sandbox="allow-scripts allow-forms allow-downloads" referrerpolicy="no-referrer" title="${e(version.artifactTitle)} — version ${e(version.number)}" src="${e(version.previewUrl||`/preview/${version.id}/index.html`)}"></iframe>`:editing?`<textarea id="document-editor" class="document-editor" aria-label="Design document" spellcheck="true">${e(sessionStorage.getItem(`byo-freedom.edit.${design.id}`)??snap?.document??'')}</textarea>`:snap?`<article class="document markdown-content">${renderMarkdown(snap.document||'')}</article>`:`<div class="empty"><h3>Your design grows with the conversation.</h3><p>Tell the agent what you have in mind. Each reply saves an immutable revision. A new visible design begins after a successful artefact build.</p></div>`;
app.innerHTML=header()+`<main class="workspace-shell ${impl?'build-workspace':'design-workspace'}">${breadcrumb([['My Projects','/projects'],['Project',`/projects/${design.projectId}`],[kind==='design'?'Your design':'Implementation']])}<div class="workspace-heading"><div><h1>${kind==='design'?`<button class="title-edit" data-action="rename" title="Edit design title">${e(design.title||'New design')} <span class="muted" style="font-size:.75rem">✎</span></button>`:e(design.title)}</h1><p class="muted">${kind==='design'?'A conversation to develop your idea':'Build and test your working artefact'}</p></div><div class="row">${me!.admin?`<button class="small" data-action="design-brand">Brand exceptions</button>${kind==='design'?'<button class="small" data-action="build-options">Build options</button>':''}`:''}${kind==='design'?`<button class="primary build-now" data-action="implement-current" ${!design.currentSnapshotId||selectedVersion||selectedSnapshot&&selectedSnapshot!==design.currentSnapshotId||data.activeJob||editing||me!.admin&&!me!.integration?.adminBuildAvailable||imageUploadBusy(id)?'disabled':''}>Build this now</button>`:''}<a class="small" href="/sites/${e(design.projectId)}" target="_blank" rel="noopener">Project site ↗</a></div></div>${designModeNav(data,impl)}${kind==='design'&&(selectedVersion||selectedSnapshot&&selectedSnapshot!==design.currentSnapshotId)?'<p class="build-readiness help">Build this now uses the latest saved design. <button class="small" data-action="latest-design">Return to latest design</button></p>':''}${kind==='design'&&!design.currentSnapshotId?'<p class="build-readiness help">Complete an interview reply or save a design revision to enable Build this now.</p>':''}${kind==='design'&&data.activeJob?'<p class="build-readiness help">A design or build turn is in progress. Wait for it to finish before starting a new build.</p>':''}${impl&&data.buildAvailable===false?`<div class="build-unavailable" role="status"><strong>Build waiting for setup</strong><p>${e(data.buildBlocker)}</p><a href="#/designs/${e(design.id)}">Continue your design ↗</a></div>`:''}${impl?`<div class="implementation-banner"><strong>Pinned design:</strong> Design ${e(data.designPin?.designNumber||1)} · ${e(data.snapshot?.title||'Selected revision')} · ${e(date(data.snapshot?.createdAt))}${impl.startingVersionId?` · Starting version: ${e(impl.startingVersionId.slice(0,8))}`:''}. Interview changes create new snapshots and do not change this build.</div>`:''}<div class="mobile-tabs" role="tablist" aria-label="Workspace view"><button role="tab" aria-selected="${tab==='chat'}" class="${tab==='chat'?'active':''}" data-tab="chat">Chat</button><button role="tab" aria-selected="${tab==='preview'}" class="${tab==='preview'?'active':''}" data-tab="preview">Preview</button></div>${importMarkup(data.importedSource)}<div class="workspace" data-tab="${e(tab)}"><section class="panel chat-panel" aria-label="${impl?'Implementation conversation':'Design interview'}"><div class="panel-head"><span class="panel-label"><span class="dot ${impl?'orange':''}"></span>${impl?'Implementation chat':'Your interview'}</span><span class="muted" style="font-size:.71rem">${impl?'Private build · site publishing is separate':'Private conversation'}</span></div><div class="messages" aria-live="polite">${(data.messages||[]).length?data.messages.map((m:RecordData)=>`<div class="message ${m.role==='user'?'user':m.role==='system'?'system':''}"><div class="speaker">${m.role==='user'?'You':m.role==='assistant'?(impl?'Builder':'Design agent'):'Workshop'}</div><div class="markdown-content">${renderMarkdown(m.content||'')}</div>${kind==='design'?imageReferences(m.images):''}${impl&&m.jobId?buildResultCards(m.jobId,data,versions):''}</div>`).join(''):`<div class="message"><div class="speaker">Your workshop</div>${impl?data.buildAvailable===false?'Your saved design is pinned here. You can draft build notes below; sending is unavailable until participant building is safely configured.':'You’ve selected a design snapshot. Tell the builder what you’d like to create or improve.':data.importedSource?'What would you like to change or build on in this artefact? Tell us your goal; the reference version is available to the interviewer.':'What do freedom and Bitcoin mean to you? Tell us about a tool you need, a vision you want to explain, or a trick you wish you could share.'}</div>`}${impl?(data.jobs||[]).filter((j:RecordData)=>!(data.messages||[]).some((m:RecordData)=>m.jobId===j.id)).map((j:RecordData)=>buildResultCards(j.id,data,versions)).join(''):''}${failed?`<div class="error-box"><strong>This turn needs attention.</strong><p>${e(failed.error||failed.progress||'The run was interrupted. Your message is saved.')}</p>${failed.status==='conflict'?`<button class="small" data-rebase="${e(failed.id)}">Rebase interview</button>`:`<button class="small" data-retry="${e(failed.id)}">Retry saved turn</button>`}</div>`:''}</div>${job?renderAgentActivity(job):''}${job?`<div class="progress" role="status"><span class="pulse"></span>${e(job.progress||job.message||'Your agent is working. It’s safe to leave this page.')} <span class="muted">(${e(job.status)})</span>${(job.status==='uncertain'||job.pollError||job.deliveryState?.delivery?.status==='failed')?` <button type="button" class="small ghost" data-recover="${e(job.id)}">Check for reply</button>`:''}</div>`:''}<form class="composer" id="message-form"><label class="visually-hidden" for="message-input">${impl?'Message the builder':'Respond to your design agent'}</label><textarea id="message-input" name="message" rows="3" ${kind==='design'&&draftImages(id).length?'':'required'} placeholder="${impl?'What should we build or improve?':'Your thoughts, questions, and ideas…'}">${e(storageGet(draftKey(kind,id))||'')}</textarea>${kind==='design'?imageComposer(id,me?.integration?.interviewImages===true,!!job):''}<div class="composer-footer"><span class="help">${version?`Feedback includes artefact version ${e(version.number)}.`:impl?'Builds stay linked to the selected design.':'Replies update this design until an artefact is built.'}</span><button class="primary send" type="submit" ${job||impl&&data.buildAvailable===false?'disabled':''}>${job?'Working…':impl&&data.buildAvailable===false?'Build unavailable':'Send ↗'}</button></div></form></section><section class="panel preview-panel" aria-label="Design and artefact preview"><div class="panel-head"><span class="panel-label"><span class="dot ${version?'orange':''}"></span>${version?`Artefact · Version ${e(version.number)} · Preview test data${version.outdatedBrand?' · older / unknown brand':''}`:editing?'Edit design':'Design preview'}</span><div class="row">${version?`<button class="small" data-open-app="${e(version.id)}">Open app · saved data</button><a class="small" target="_blank" rel="noopener" href="${e(version.previewUrl||`/preview/${version.id}/index.html`)}">Open ↗</a>${me!.admin?`<button class="small" data-data-permissions="${e(version.artifactId)}" data-version="${e(version.id)}">Data permissions</button><button class="small" data-publish="${e(version.artifactId)}" data-version="${e(version.id)}">${version.sitePublished?'Published ✓':version.published?'Add to project site':'Publish version'}</button>`:''}`:kind==='design'?editing?'<button class="small" data-action="cancel-edit">Cancel</button><button class="primary small" data-action="save-edit">Save revision</button>':'<button class="small" data-action="edit-document">Edit design</button>':''}</div></div><div class="preview-content">${content}</div><div class="history"><div class="history-title">Design milestones <span style="color:var(--purple)">●</span> &nbsp; Artefact versions <span style="color:var(--orange)">●</span></div><div class="history-items">${(data.milestones||(data.snapshot?[{...data.snapshot,snapshotId:data.snapshot.id,number:data.designPin?.designNumber||1,state:'pinned'}]:[])).map((s:RecordData)=>`<button class="snapshot ${!version&&s.snapshotId===snap?.id?'selected':''}" data-snapshot="${e(s.snapshotId)}" title="${e(date(s.createdAt))} · ${e(s.revisionCount||1)} immutable revisions">Design ${e(s.number)} · ${e(s.state)}</button>`).join('')}${versions.map(v=>`<button class="artifact ${v.id===version?.id?'selected':''}" data-version-select="${e(v.id)}" title="${e(v.artifactTitle)}">Version ${e(v.number)}${v.published?' · public':''}${v.outdatedBrand?' · older brand':''}</button>`).join('')}${!snaps.length&&!versions.length?'<span class="help">Your saved history will appear here.</span>':''}</div></div></section></div></main>`;
if(kind==='design')mountInterviewImages((path,method,data)=>method==='POST'&&path.endsWith('/images')?runBrowserOperation(api,nstackSigner(),path,data):api(path,method,data),id,me?.integration?.interviewImages===true,!!job,modal);document.querySelector('[data-open-app]')?.addEventListener('click',()=>{if(version)openNStackApp(api,modal,{id:version.id,previewUrl:version.previewUrl,artifactTitle:version.artifactTitle},nstackSigner())});if(version){const frame=document.querySelector<HTMLIFrameElement>('.preview-content iframe');if(frame)attachNStackBridge(frame,version.id,api,'preview',nstackSigner());}document.querySelectorAll('[data-data-permissions]').forEach(el=>el.addEventListener('click',()=>act(()=>nstackPermissions(api,modal,el.getAttribute('data-data-permissions')!,el.getAttribute('data-version')!))));const newMessages=document.querySelector('.messages')!;newMessages.scrollTop=atBottom?newMessages.scrollHeight:previousScroll;if(editorScroll)document.querySelector('#document-editor')!.scrollTop=editorScroll;document.querySelector('#message-input')!.addEventListener('input',saveWorkspaceState);const chatInput=document.querySelector<HTMLTextAreaElement>('#message-input')!;chatInput.addEventListener('compositionstart',()=>{chatComposing=true});chatInput.addEventListener('compositionend',()=>{chatComposing=false;lastChatCompositionEnd=Date.now()});chatInput.addEventListener('keydown',ev=>{if(!isChatSubmitKey(ev,chatComposing,lastChatCompositionEnd))return;ev.preventDefault();const form=document.querySelector<HTMLFormElement>('#message-form')!;const submit=form.querySelector<HTMLButtonElement>('[type=submit]')!;if(!ev.repeat&&!busy&&!submit.disabled&&(chatInput.value.trim()||kind==='design'&&draftImages(id).length))form.requestSubmit();});document.querySelector('#document-editor')?.addEventListener('input',saveWorkspaceState);if(wasFocused==='message-input'){const input=document.querySelector<HTMLTextAreaElement>('#message-input')!;input.focus({preventScroll:true});if(selection!==null)input.setSelectionRange(selection,selection)}document.querySelector('#message-form')!.addEventListener('submit',ev=>{ev.preventDefault();act(()=>sendMessage(kind,id))});document.querySelector<HTMLSelectElement>('#build-conversation')?.addEventListener('change',ev=>location.hash='#/implementations/'+(ev.target as HTMLSelectElement).value);document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>{tab=el.getAttribute('data-tab')!;localStorage.setItem('byo-freedom.tab',tab);document.querySelector('.workspace')!.setAttribute('data-tab',tab);document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t.getAttribute('data-tab')===tab);t.setAttribute('aria-selected',String(t.getAttribute('data-tab')===tab))})}));document.querySelectorAll('[data-snapshot]').forEach(el=>el.addEventListener('click',()=>{saveWorkspaceState();selectedSnapshot=el.getAttribute('data-snapshot');selectedVersion=null;sessionStorage.setItem(`byo-freedom.selection.${kind}.${id}`,JSON.stringify({snapshotId:selectedSnapshot,versionId:null}));editing=false;act(()=>workspace(kind,id))}));document.querySelectorAll('[data-version-select]').forEach(el=>el.addEventListener('click',()=>{saveWorkspaceState();selectedVersion=el.getAttribute('data-version-select');sessionStorage.setItem(`byo-freedom.selection.${kind}.${id}`,JSON.stringify({snapshotId:null,versionId:selectedVersion}));editing=false;act(()=>workspace(kind,id))}));document.querySelectorAll('[data-rebase]').forEach(el=>el.addEventListener('click',()=>act(async()=>{const jobId=el.getAttribute('data-rebase')!;const key=`byo-freedom.rebase.${jobId}`;const requestId=storageGet(key)||crypto.randomUUID();localStorage.setItem(key,requestId);await api(`/api/jobs/${jobId}/recover`,'POST',{action:'rebase',requestId});localStorage.removeItem(key);toast('Interview continues from the latest saved design');await workspace(kind,id)})));document.querySelectorAll('[data-recover]').forEach(el=>el.addEventListener('click',()=>act(async()=>{await api(`/api/jobs/${el.getAttribute('data-recover')}/recover`,'POST',{});toast('Run status checked');await workspace(kind,id)})));document.querySelectorAll('[data-retry]').forEach(el=>el.addEventListener('click',()=>act(async()=>{await api(`/api/jobs/${el.getAttribute('data-retry')}/retry`,'POST',{});await workspace(kind,id)})));document.querySelectorAll('[data-publish]').forEach(el=>el.addEventListener('click',()=>act(async()=>{await api(`/api/artifacts/${el.getAttribute('data-publish')}/publish`,'POST',{versionId:el.getAttribute('data-version')});toast('Version published to the project site');await workspace(kind,id)})));schedulePoll(kind,id,!!job)}
function schedulePoll(kind:string,id:string,working:boolean){clearTimeout(pollTimer);pollTimer=setTimeout(()=>{if(activeRoute===`${kind}/${id}`&&!document.hidden)workspace(kind,id,true).catch(err=>{console.warn('Progress refresh failed',err);schedulePoll(kind,id,working)})},working?2500:10000)}
async function sendMessage(kind:string,id:string){if(kind==='design'&&imageUploadBusy(id))throw Error('Wait for the image upload to finish.');const imageIds=kind==='design'?draftImages(id).map(i=>i.id):[];if(kind==='implementation'&&current?.buildAvailable===false)throw Error(current.buildBlocker);const input=document.querySelector<HTMLTextAreaElement>('#message-input')!;const content=input.value.trim();if(!content&&!imageIds.length)return;const pendingKey=`byo-freedom.pending.${kind}.${id}`;let pending:RecordData|null=null;try{pending=JSON.parse(storageGet(pendingKey)||'null')}catch{}const data:RecordData=pending?.content===content&&(pending?.artifactVersionId??null)===(kind==='design'?selectedVersion:null)&&JSON.stringify(pending?.imageIds??[])===JSON.stringify(imageIds)?pending!:{content,requestId:crypto.randomUUID(),...(imageIds.length?{imageIds}:{})};if(kind==='design'&&selectedVersion)data.artifactVersionId=selectedVersion;localStorage.setItem(pendingKey,JSON.stringify(data));await api(`/api/${kind==='design'?'designs':'implementations'}/${id}/messages`,'POST',data);input.value='';if(kind==='design')clearDraftImages(id);localStorage.removeItem(pendingKey);localStorage.removeItem(draftKey(kind,id));await workspace(kind,id)}
async function saveEdit(rename=false){const design=current!.design;const snaps=current!.snapshots||[];const latest=snaps.find((s:RecordData)=>s.id===design.currentSnapshotId)||snaps.at(-1);const selected=snaps.find((s:RecordData)=>s.id===selectedSnapshot)||latest;if(rename){modal('Name your design',`<label>Design title<input name="title" value="${e(design.title)}" required maxlength="160"></label><div class="modal-actions"><button type="submit" class="primary">Save title</button></div>`,async form=>{await api(`/api/designs/${design.id}`,'PATCH',{title:new FormData(form).get('title'),document:latest?.document||`# ${new FormData(form).get('title')}\n\n## Open questions\nWhat would give you more freedom?`,expectedSnapshotId:design.currentSnapshotId||null});selectedSnapshot=null;await workspace('design',design.id)});return}const documentText=document.querySelector<HTMLTextAreaElement>('#document-editor')!.value;const base=JSON.parse(sessionStorage.getItem(`byo-freedom.edit-base.${design.id}`)||JSON.stringify({snapshotId:design.currentSnapshotId||null,title:design.title}));try{await api(`/api/designs/${design.id}`,'PATCH',{title:base.title,document:documentText,expectedSnapshotId:base.snapshotId});editing=false;selectedSnapshot=null;selectedVersion=null;sessionStorage.removeItem(`byo-freedom.edit.${design.id}`);await workspace('design',design.id);toast('Design updated; immutable revision saved')}catch(err){if((err as any).status===409){modal('Your design changed',`<p>A new snapshot was saved while you were editing. Your draft is preserved in this browser.</p><p class="muted">Reload the latest design, compare it with your draft, and save your changes again.</p><div class="modal-actions"><button type="submit" class="primary">Load latest snapshot</button></div>`,async()=>{editing=false;selectedSnapshot=null;await workspace('design',design.id)})}else throw err}}
